file.content:
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: #2b3236;
  background: #ffffff;
}

a {
  color: inherit;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px 64px;
}

.logo {
  font-size: 19px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  color: #4d585e;
}

.hero {
  height: 430px;
  padding: 72px 64px 0;
}

.hero-text {
  max-width: 400px;
}

h1 {
  margin: 0 0 16px;
  font-size: 30px;
  font-weight: 500;
  line-height: 1.25;
}

.hero-text p {
  margin: 0 0 24px;
  color: #4d585e;
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: #1f5f7a;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

.lower {
  display: flex;
  gap: 48px;
  padding: 0 64px;
}

.today {
  flex: 0 0 300px;
}

h2 {
  margin: 0 0 6px;
  font-size: 13px;
  font-weight: 500;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  color: #4d585e;
}

th,
td {
  padding: 2px 0;
  text-align: left;
  font-weight: 400;
}

th {
  color: #7a858b;
}

.points {
  display: flex;
  gap: 32px;
}

.point h3 {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 500;
}

.point p {
  margin: 0;
  color: #4d585e;
}

.point {
  flex: 1;
}

content.content:
{"id":"phone-tablet-layout-breaks","rank":1,"title":"The phone and tablet layouts break: the page scrolls sideways and the feature columns shrink to single words","target":"No sideways scroll on the phone (page width equal to viewport width); feature text at 45 to 75 characters per line, with headings that do not break mid-phrase; nav on one line or behind a menu","fix_direction":"Below tablet width, stack the tide sample and the three points into one column, and keep the nav to one line or put it behind a menu."}
{"id":"empty-hero-small-proof","rank":2,"title":"The hero's right side is empty, and the tide sample that shows the product is pushed down and set smaller than the feature headings","target":"The sample harbor page shown in the hero's empty right half, with its text at least at body size (15 px)","fix_direction":"Move the sample harbor page up into the empty right half of the hero, and set it at least at body size, so the first screen shows what a berth holder would see."}
{"id":"sample-hides-differences","rank":3,"title":"The sample shows only tide times, the one thing that is not different, and the page never compares Tidewell with what the harbor office uses now","target":"A sample that shows the whole page a berth holder gets, with gate times, pontoon depth and a notice in it, and a comparison with how the office posts these now","fix_direction":"Make the sample show gate times, pontoon depth and a notice. Add a comparison with the office's current way of posting these; the maker must supply the specifics of that current way and the figures for the sample."}
{"id":"table-header-contrast","rank":null,"title":"The table column headers Tide, Time and Height are too faint","target":"contrast of at least 4.5:1","fix_direction":"Darken the headers to the body gray."}
{"id":"too-many-type-sizes","rank":null,"title":"Five type sizes, and 13 and 12 are too close to read as different levels","target":"three or four type sizes, with the table heading matching the 15 px feature headings","fix_direction":"Use three or four sizes, and let the table heading match the 15 px feature headings."}
{"id":"heading-baseline-step","rank":null,"title":"The table heading and the feature headings start at the same top but sit on different baselines","target":"the headings on the same baseline","fix_direction":"Put them on the same baseline."}
{"id":"straight-apostrophe","rank":null,"title":"The apostrophe in \"day's\" in the hero paragraph is straight","target":"a curly apostrophe","fix_direction":"Use a curly apostrophe."}

