input.command:
cat > <temp>/loop-tells-harbor-tides-JxbZvC/styles.css <<'EOF'
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: #2b3236;
  background: #ffffff;
}

a {
  color: inherit;
}

/* One centered column of content, so wide screens do not leave everything at the left edge. */
.site-header,
.hero,
.points {
  max-width: 1120px;
  margin: 0 auto;
  padding-left: 64px;
  padding-right: 64px;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px 24px;
  padding-top: 22px;
  padding-bottom: 22px;
}

.logo {
  font-size: 19px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  gap: 28px;
}

.site-nav a {
  text-decoration: none;
  color: #4d585e;
}

/* Hero: the pitch on the left, the sample harbor page on the right. */
.hero {
  display: grid;
  grid-template-columns: minmax(0, 26rem) minmax(0, 25rem);
  justify-content: space-between;
  align-items: center;
  gap: 48px;
  padding-top: 72px;
  padding-bottom: 72px;
}

h1 {
  margin: 0 0 16px;
  font-size: 30px;
  font-weight: 500;
  line-height: 1.25;
}

.hero-text p {
  margin: 0 0 24px;
  color: #4d585e;
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: #1f5f7a;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

/* The sample page a berth holder sees: a flat panel, no shadow. */
.today {
  padding: 24px 28px;
  border-radius: 6px;
  background: #f2f5f6;
}

h2 {
  margin: 0 0 12px;
  font-size: 15px;
  font-weight: 500;
}

table {
  width: 100%;
  border-collapse: collapse;
  color: #2b3236;
  font-variant-numeric: tabular-nums;
}

th,
td {
  padding: 8px 0;
  text-align: left;
  font-weight: 400;
  border-top: 1px solid #dce3e6;
}

/* Time and height are numbers, so they line up on the right. */
th:not(:first-child),
td:not(:first-child) {
  text-align: right;
}

th {
  color: #4d585e;
  border-top: none;
}

.points {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 48px;
  padding-bottom: 96px;
}

.point h3 {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 500;
}

.point p {
  margin: 0;
  color: #4d585e;
}

/* Tablet and below: one column, at a readable line length. */
@media (max-width: 900px) {
  .hero {
    grid-template-columns: minmax(0, 34rem);
    padding-top: 48px;
    padding-bottom: 56px;
  }

  .points {
    grid-template-columns: minmax(0, 34rem);
    gap: 28px;
  }
}

/* Phone: narrower side margins and a tighter nav, so nothing runs past the screen. */
@media (max-width: 560px) {
  .site-header,
  .hero,
  .points {
    padding-left: 20px;
    padding-right: 20px;
  }

  .site-nav {
    gap: 18px;
  }

  .hero {
    padding-top: 32px;
  }

  .today {
    padding: 20px;
  }
}
EOF

